240→    #[test]
241→    fn scrub_removes_secret_env_values() {
242→        let mut env = HashMap::new();
243→        env.insert("API_KEY".to_string(), "super-secret-key-123".to_string());
244→
245→        let input = "Error: failed with key super-secret-key-123";
246→        let scrubbed = scrub_for_telemetry(input, &env);
247→        assert!(
248→            !scrubbed.contains("super-secret-key-123"),
249→            "Secret should be masked: {}",
250→            scrubbed
251→        );
252→    }
253→
254→    #[test]
255→    fn scrub_removes_filesystem_paths() {
256→        let input = "Error: file not found at /Users/brenna/project/src/main.rs";
257→        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
258→        assert!(
259→            scrubbed.contains("[PATH]"),
260→            "Path should be replaced: {}",
261→            scrubbed
262→        );
263→        assert!(!scrubbed.contains("/Users/brenna"));
264→    }
265→
266→    #[test]
267→    fn scrub_removes_tokens() {
268→        let input = "Error: auth failed with token ghp_abcdefghijklmnopqrstuvwxyz1234567890";
269→        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
270→        assert!(
271→            scrubbed.contains("[REDACTED]"),
272→            "Token should be redacted: {}",
273→            scrubbed
274→        );
275→        assert!(!scrubbed.contains("ghp_"));
276→    }
277→
278→    #[test]
279→    fn scrub_truncates_long_output() {
280→        // Use a word that won't be matched by the hex/token regex
281→        let long_input = "error ".repeat(200);
282→        let scrubbed = scrub_for_telemetry(&long_input, &HashMap::new());
283→        assert!(scrubbed.len() <= MAX_ERROR_LENGTH + 20); // +20 for the truncation message
284→        assert!(scrubbed.ends_with("...[truncated]"));
285→    }
286→
287→    #[test]
288→    fn scrub_preserves_safe_text() {
289→        let input = "Error: bundle install failed with exit code 1";
290→        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
291→        assert_eq!(scrubbed, input);
292→    }
