324→
325→    #[test]
326→    fn telemetry_auto_sends_when_always() {
327→        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
328→        let mut ui = crate::ui::MockUI::new();
329→
330→        let result = prompt_telemetry(&mut ui, &report, Some("always")).unwrap();
331→        assert_eq!(result, TelemetryConsent::Always);
