  1→//! Integration tests for CLI argument parsing.
  2→// The cargo_bin function is marked deprecated in favor of cargo_bin! macro,
  3→// but both work correctly. Suppressing until assert_cmd stabilizes the new API.
  4→#![allow(deprecated)]
  5→
  6→use assert_cmd::cargo::cargo_bin;
  7→use assert_cmd::Command;
  8→use predicates::prelude::*;
  9→use std::fs;
 10→use tempfile::TempDir;
 11→
 12→fn setup_project(config: &str) -> TempDir {
 13→    let temp = TempDir::new().unwrap();
 14→    let bivvy_dir = temp.path().join(".bivvy");
 15→    fs::create_dir_all(&bivvy_dir).unwrap();
 16→    fs::write(bivvy_dir.join("config.yml"), config).unwrap();
 17→    temp
 18→}
 19→
 20→const SIMPLE_CONFIG: &str = r#"
 21→app_name: Test
 22→steps:
 23→  hello:
 24→    command: echo hello
 25→workflows:
 26→  default:
 27→    steps: [hello]
 28→  custom:
 29→    steps: [hello]
 30→"#;
 31→
 32→#[test]
 33→fn cli_no_args_runs_default() -> Result<(), Box<dyn std::error::Error>> {
 34→    let temp = setup_project(SIMPLE_CONFIG);
 35→    let mut cmd = Command::new(cargo_bin("bivvy"));
 36→    cmd.current_dir(temp.path());
 37→    cmd.assert()
 38→        .success()
 39→        .stdout(predicate::str::contains("Setup complete!"));
 40→    Ok(())
 41→}
