200→    }
201→
202→    /// Clear all captured interactions.
203→    pub fn clear(&mut self) {
204→        self.messages.clear();
205→        self.successes.clear();
206→        self.warnings.clear();
207→        self.errors.clear();
208→        self.headers.clear();
209→        self.hints.clear();
210→        self.progress.clear();
211→        self.spinners.clear();
212→        self.run_headers.clear();
213→        self.error_blocks.clear();
214→        self.summaries.clear();
215→        self.prompts_shown.clear();
216→    }
217→}
