    // --- Offline queueing / save_report_to tests ---

    #[test]
    fn rapid_saves_for_same_step_produce_distinct_files() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report(
            "bundler",
            "bundle install",
            Some(1),
            "build error",
            "retry",
            &HashMap::new(),
        );

        for _ in 0..5 {
            save_report_to(&report, temp.path()).unwrap();
        }

        let files: Vec<_> = std::fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .collect();
        assert_eq!(
            files.len(),
            5,
            "All 5 reports should be saved as distinct files, got: {:?}",
            files.iter().map(|f| f.file_name()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn concurrent_saves_from_threads_preserve_all_reports() {
        let temp = tempfile::TempDir::new().unwrap();
        let dir = temp.path().to_path_buf();

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let dir = dir.clone();
                std::thread::spawn(move || {
                    let report = build_report(
                        "worker",
                        &format!("task {}", i),
                        Some(i),
                        &format!("error {}", i),
                        "retry",
                        &HashMap::new(),
                    );
                    save_report_to(&report, &dir).unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let files: Vec<_> = std::fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .collect();
        assert_eq!(
            files.len(),
            10,
            "All 10 concurrent saves should produce distinct files, got: {:?}",
            files.iter().map(|f| f.file_name()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn saved_report_deserializes_back_correctly() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report(
            "cargo",
            "cargo build",
            Some(101),
            "linking failed",
            "shell → retry",
            &HashMap::new(),
        );

        let path = save_report_to(&report, temp.path()).unwrap();
        let content = std::fs::read_to_string(&path).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&content).unwrap();

        assert_eq!(loaded.step_name, "cargo");
        assert_eq!(loaded.command_scrubbed, "cargo build");
        assert_eq!(loaded.exit_code, Some(101));
        assert_eq!(loaded.error_scrubbed, "linking failed");
        assert_eq!(loaded.recovery_action, "shell → retry");
        assert_eq!(loaded.bivvy_version, report.bivvy_version);
        assert_eq!(loaded.platform, report.platform);
    }

    #[test]
    fn save_creates_nested_directory_structure() {
        let temp = tempfile::TempDir::new().unwrap();
        let nested = temp.path().join("a").join("b").join("c");
        let report = build_report(
            "test",
            "echo ok",
            Some(0),
            "",
            "retry",
            &HashMap::new(),
        );

        let path = save_report_to(&report, &nested).unwrap();
        assert!(path.exists());
        assert!(nested.is_dir());
    }

    #[test]
    fn saves_for_different_steps_produce_separate_files() {
        let temp = tempfile::TempDir::new().unwrap();
        let steps = ["bundler", "cargo", "npm", "pip"];

        for step in &steps {
            let report = build_report(step, "install", Some(1), "err", "retry", &HashMap::new());
            save_report_to(&report, temp.path()).unwrap();
        }

        let files: Vec<_> = std::fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .collect();
        assert_eq!(files.len(), steps.len());

        for step in &steps {
            assert!(
                files
                    .iter()
                    .any(|f| f.file_name().to_string_lossy().contains(step)),
                "Should have a file for step '{}'",
                step
            );
        }
    }

    #[test]
    fn saved_report_filename_contains_step_name_and_yml_extension() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report(
            "bundler",
            "bundle install",
            Some(1),
            "error",
            "retry",
            &HashMap::new(),
        );

        let path = save_report_to(&report, temp.path()).unwrap();
        let filename = path.file_name().unwrap().to_string_lossy();
        assert!(filename.contains("bundler"), "Filename should contain step name");
        assert!(filename.ends_with(".yml"), "Filename should end with .yml");
    }

    // --- Prompt coverage tests ---

    #[test]
    fn prompt_returns_always_when_selected() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "always");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Always);
        assert_eq!(ui.prompts_shown(), &["telemetry_failure"]);
    }

    #[test]
    fn prompt_returns_never_when_selected() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "never");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Never);
        assert_eq!(ui.prompts_shown(), &["telemetry_failure"]);
    }

    #[test]
    fn prompt_with_unknown_preference_shows_prompt() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "send");

        let result = prompt_telemetry(&mut ui, &report, Some("garbage")).unwrap();
        assert_eq!(result, TelemetryConsent::Send);
        assert_eq!(ui.prompts_shown(), &["telemetry_failure"]);
    }

    #[test]
    fn prompt_messages_contain_report_details() {
        let report = build_report(
            "bundler",
            "bundle install",
            Some(42),
            "Gem not found",
            "shell → retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
